// Simple markdown parser
var marked = {
    parse: function(markdown) {
        if (!markdown) return '';

        let html = markdown
            // Escape HTML
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')

            // Headers
            .replace(/^### (.*$)/gim, '<h3>$1</h3>')
            .replace(/^## (.*$)/gim, '<h2>$1</h2>')
            .replace(/^# (.*$)/gim, '<h1>$1</h1>')

            // Bold
            .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
            .replace(/__(.+?)__/g, '<strong>$1</strong>')

            // Italic
            .replace(/\*(.+?)\*/g, '<em>$1</em>')
            .replace(/_(.+?)_/g, '<em>$1</em>')

            // Code
            .replace(/`([^`]+)`/g, '<code>$1</code>')

            // Links
            .replace(/\[([^\]]+)\]\(([^\)]+)\)/g, '<a href="$2">$1</a>')

            // Line breaks
            .replace(/\n\n/g, '</p><p>')
            .replace(/\n/g, '<br>');

        // Unordered lists
        html = html.replace(/^\* (.+)$/gim, function(match) {
            return '<li>' + match.substring(2) + '</li>';
        });
        html = html.replace(/(<li>.*<\/li>)/s, '<ul>$1</ul>');

        // Ordered lists
        html = html.replace(/^\d+\. (.+)$/gim, function(match) {
            return '<li>' + match.substring(match.indexOf('.') + 2) + '</li>';
        });

        // Wrap in paragraphs if no block elements
        if (!html.match(/<(h[1-6]|ul|ol|p)>/)) {
            html = '<p>' + html + '</p>';
        }

        return html;
    },

    setOptions: function(options) {
        // Stub for compatibility
    }
};
